  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', 'University of Alberta', 'Studied political science then psychology; graduated with BA in psychology.', 'range', 1980, 1984, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', 'McGill University — PhD', 'Completed PhD in clinical psychology; trained under Robert Pihl.', 'range', 1985, 1991, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', 'Harvard professor', 'Taught personality psychology at Harvard; moved to University of Toronto.', 'range', 1993, 1998, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', 'Maps of Meaning published', 'Dense academic work on mythology, belief, and human behavior.', 'point', 1999, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Activities', 'Bill C-16 controversy', 'Refused to use compelled pronouns; YouTube lectures went viral globally.', 'point', 2016, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', '12 Rules for Life published', 'Self-help book sold 5M+ copies; became global cultural phenomenon.', 'point', 2018, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Health', 'Benzodiazepine addiction & coma', 'Wife''s cancer diagnosis led to dependency; entered medical coma for treatment.', 'range', 2019, 2020, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000001d7', 'Work & Education', 'Beyond Order published', 'Second major self-help book; written during and after severe health crisis.', 'point', 2021, null, '#10b981');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001d8', 'Place & Travel', 'Nairobi, Kenya', 'Born in Nairobi; family moved back to England in 1949 when he was 8.', 'range', 1941, 1949, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Place & Travel', 'Oxford, England', 'Spent most of his career in Oxford; deeply tied to the university.', 'range', 1959, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Work & Education', 'Oxford — BA Zoology', 'Studied zoology under Nobel laureate Nikolaas Tinbergen.', 'range', 1959, 1962, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Work & Education', 'The Selfish Gene published', 'Landmark popular science book; coined the term ''meme''.', 'point', 1976, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Work & Education', 'The Blind Watchmaker', 'Defended Darwinian evolution against intelligent design; major bestseller.', 'point', 1986, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Work & Education', 'Oxford Chair for Public Understanding', 'Held Simonyi Professorship for Public Understanding of Science 1995–2008.', 'range', 1995, 2008, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Work & Education', 'The God Delusion published', 'New Atheism manifesto; sold 3M+ copies and sparked global debate.', 'point', 2006, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Health', 'Stroke', 'Suffered a minor stroke; recovered and continued writing and public speaking.', 'point', 2016, null, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000001d8', 'Activities', 'Richard Dawkins Foundation', 'Founded RDFRS to promote scientific literacy and secularism globally.', 'range', 2006, 2026, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001d9', 'Place & Travel', 'Los Angeles, California', 'Born and raised in LA; mother is Jewish, father was a Quaker actor.', 'range', 1967, 1986, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Work & Education', 'Stanford University', 'Enrolled in English then philosophy; left to travel and explore Buddhism.', 'range', 1986, 1992, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Activities', 'Meditation retreats in India & Nepal', 'Spent years studying under meditation teachers in Asia; years-long hiatus from Stanford.', 'range', 1992, 2000, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Work & Education', 'Stanford BA in Philosophy', 'Returned to complete degree; 9/11 prompted him to finish and write his first book.', 'point', 2000, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Work & Education', 'The End of Faith published', 'Post-9/11 critique of religion became NYT bestseller; launched New Atheism wave.', 'point', 2004, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Work & Education', 'UCLA — PhD Neuroscience', 'Earned doctorate studying the neural basis of belief and disbelief.', 'range', 2002, 2009, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Work & Education', 'Waking Up app & podcast', 'Launched subscription meditation app and podcast; millions of subscribers.', 'range', 2018, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Activities', 'Martial arts — Jiu-Jitsu', 'Long-time Brazilian jiu-jitsu practitioner; discusses combat sports publicly.', 'range', 2000, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001d9', 'Relations & Family', 'Married Annaka Harris', 'Married author and editor Annaka Harris; collaborator on science outreach.', 'point', 2004, null, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001da', 'Place & Travel', 'Portsmouth, England', 'Born in Portsmouth; son of Royal Navy commander; moved frequently.', 'range', 1949, 1967, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001da', 'Work & Education', 'Balliol College, Oxford', 'Read Philosophy, Politics and Economics; became president of Oxford Union.', 'range', 1967, 1970, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001da', 'Work & Education', 'New Statesman & The Nation', 'Wrote for left-wing press; correspondent and literary critic in London.', 'range', 1973, 1992, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001da', 'Place & Travel', 'Washington D.C., USA', 'Relocated to Washington; became Vanity Fair columnist and US citizen.', 'range', 1982, 2011, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001da', 'Work & Education', 'Vanity Fair columnist', 'Long-time contributing editor; wrote on politics, culture, and foreign affairs.', 'range', 1992, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001da', 'Work & Education', 'god is Not Great published', 'Polemical critique of religion became #1 NYT bestseller.', 'point', 2007, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001da', 'Health', 'Esophageal cancer diagnosis', 'Diagnosed with esophageal cancer; wrote and debated publicly until near death.', 'range', 2010, 2011, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000001da', 'Activities', 'Became US citizen', 'Naturalized US citizen; event coincided with Iraq War support controversy.', 'point', 2007, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001da', 'Work & Education', 'Mortality published posthumously', 'Essay collection on dying with dignity published after his death from cancer.', 'point', 2012, null, '#10b981');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001db', 'Place & Travel', 'Philadelphia, Pennsylvania', 'Born in Philadelphia to Jewish immigrant family; father was a Hebrew scholar.', 'range', 1928, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001db', 'Work & Education', 'University of Pennsylvania', 'Studied linguistics under Zellig Harris; BA, MA, and PhD all at Penn.', 'range', 1945, 1955, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001db', 'Work & Education', 'MIT — Professor of Linguistics', 'Joined MIT in 1955; remained there for over 60 years, transforming the field.', 'range', 1955, 2017, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001db', 'Work & Education', 'Syntactic Structures published', 'Revolutionized linguistics; introduced transformational generative grammar.', 'point', 1957, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001db', 'Activities', 'Vietnam War activism', 'Became leading anti-war voice; arrested at Pentagon during 1967 protest.', 'range', 1965, 1975, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001db', 'Work & Education', 'Manufacturing Consent published', 'Co-authored media criticism classic with Edward Herman; still widely read.', 'point', 1988, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001db', 'Relations & Family', 'Wife Carol died', 'Lost wife Carol of 59 years to cancer; deeply affected him personally.', 'point', 2008, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000001db', 'Place & Travel', 'Tucson, Arizona', 'Relocated to University of Arizona after remarrying Valeria Wasserman.', 'range', 2017, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001db', 'Health', 'Stroke in São Paulo', 'Suffered a stroke while in Brazil; recovered partially with ongoing care.', 'point', 2023, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001dc', 'Place & Travel', 'Ljubljana, Yugoslavia (Slovenia)', 'Born and raised in Ljubljana; grew up under socialist Yugoslavia.', 'range', 1949, 1971, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Work & Education', 'University of Ljubljana', 'Studied philosophy and sociology; MA thesis controversial for Western citations.', 'range', 1967, 1971, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Work & Education', 'PhD in Paris — Lacanian theory', 'Studied under Jacques-Alain Miller in Paris; mastered Lacan and Hegel.', 'range', 1981, 1985, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Activities', 'Slovenian presidential campaign', 'Ran for President of Slovenia''s Presidency; narrowly lost in 1990 election.', 'point', 1990, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Work & Education', 'The Sublime Object of Ideology', 'Debut English work fusing Lacan, Hegel, and Marxism; cult classic.', 'point', 1989, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Work & Education', 'Prolific philosophical output', 'Over 50 books applying psychoanalysis to popular culture and politics.', 'range', 1997, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Activities', 'The Pervert''s Guide to Cinema', 'Starred in documentary applying Lacanian theory to Hollywood films.', 'point', 2006, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Place & Travel', 'New York & London visiting posts', 'Held visiting professorships at Columbia, NYU, and Birkbeck London.', 'range', 1993, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001dc', 'Relations & Family', 'Multiple marriages', 'Married four times; personal life as unconventional as his philosophy.', 'range', 1970, 2026, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001dd', 'Place & Travel', 'Melbourne, Australia', 'Born in Melbourne to Austrian Jewish refugees who fled the Holocaust.', 'range', 1946, 1967, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Work & Education', 'University of Melbourne & Oxford', 'BA/MA at Melbourne; BPhil at Oxford''s University College studying ethics.', 'range', 1967, 1971, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Work & Education', 'Animal Liberation published', 'Foundational text of animal rights movement; launched modern veganism discourse.', 'point', 1975, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Work & Education', 'Monash University — bioethics', 'Founded and directed Centre for Human Bioethics at Monash University.', 'range', 1977, 1999, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Work & Education', 'Princeton Bioethics professor', 'Appointed Ira W. DeCamp Professor of Bioethics at Princeton University.', 'range', 1999, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Activities', 'Effective altruism movement', 'Co-founded intellectual movement; advocates giving 10%+ of income to effective charities.', 'range', 2009, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Activities', 'Veganism advocacy', 'Publicly vegan for decades; advocates plant-based diet on ethical grounds.', 'range', 1975, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001dd', 'Assets', 'Donates majority of income', 'Gives over 30% of his income to effective charities; practices what he preaches.', 'range', 1980, 2026, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001de', 'Place & Travel', 'Montreal, Quebec, Canada', 'Born and raised in Montreal''s Jewish community; bilingual upbringing.', 'range', 1954, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'McGill University & Harvard', 'BA at McGill; PhD in experimental psychology at Harvard.', 'range', 1973, 1979, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'MIT — cognitive science professor', 'Taught at MIT from 1982; research focused on language acquisition in children.', 'range', 1982, 2003, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'The Language Instinct published', 'Accessible bestseller arguing language is a biological adaptation.', 'point', 1994, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'Harvard — Johnstone Professor', 'Moved to Harvard Psychology Department; won multiple teaching awards.', 'range', 2003, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'The Better Angels of Our Nature', 'Argued violence has declined across history; transformed public debate.', 'point', 2011, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Work & Education', 'Enlightenment Now published', 'Defended Enlightenment values against pessimism; became #1 bestseller.', 'point', 2018, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001de', 'Activities', 'Time 100 Most Influential People', 'Named twice to Time''s 100 most influential people; frequent media commentator.', 'point', 2004, null, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001df', 'Place & Travel', 'Manhattan, New York City', 'Born in Manhattan; first saw night sky at Hayden Planetarium age 9.', 'range', 1958, 1976, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001df', 'Work & Education', 'Harvard University — BA Physics', 'Studied physics at Harvard; captain of the wrestling team.', 'range', 1976, 1980, '#10b981'),
