  ('a0000000-0000-0000-0000-0000000001df', 'Activities', 'Pluto reclassification', 'Led scientific case for reclassifying Pluto as a dwarf planet; global backlash.', 'point', 2006, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001df', 'Work & Education', 'Cosmos: A Spacetime Odyssey', 'Hosted reboot of Carl Sagan''s Cosmos series; 135M viewers globally.', 'range', 2014, 2020, '#10b981'),
