  ('a0000000-0000-0000-0000-0000000001df', 'Activities', 'Presidential Science Commission', 'Served on NASA advisory board and Presidential Commission on moon/Mars.', 'range', 2001, 2004, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001df', 'Health', 'Sexual misconduct allegations', 'Multiple allegations emerged in 2018; investigated by employer and reinstated.', 'point', 2018, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001e0', 'Place & Travel', 'Washington D.C.', 'Born in D.C.; father was a WWII POW who cultivated love of sundials.', 'range', 1955, 1973, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Work & Education', 'Cornell University — Mechanical Engineering', 'Studied under Carl Sagan; earned BS in mechanical engineering.', 'range', 1973, 1977, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Work & Education', 'Boeing engineer in Seattle', 'Worked as hydraulics engineer at Boeing; invented a nose fitting used on 747s.', 'range', 1977, 1986, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Work & Education', 'Almost Live! comedy writing', 'Wrote for and appeared in Seattle comedy show while pursuing science education.', 'range', 1986, 1993, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Work & Education', 'Bill Nye the Science Guy', 'Emmy-winning educational TV series 1993–98; reached millions of children.', 'range', 1993, 1998, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Activities', 'Climate change advocacy', 'Became prominent voice on climate science and science education policy.', 'range', 2000, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Activities', 'Creationism debate with Ken Ham', 'Nationally televised debate on evolution vs. creationism watched by millions.', 'point', 2014, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Work & Education', 'CEO of Planetary Society', 'Led Carl Sagan''s non-profit promoting space exploration since 2010.', 'range', 2010, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e0', 'Place & Travel', 'Los Angeles, California', 'Relocated to LA as media presence grew; frequent tech conference speaker.', 'range', 2000, 2026, '#3b82f6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001e1', 'Place & Travel', 'London, England', 'Born in Hampstead, London; fascinated by animals from early childhood.', 'range', 1934, 1957, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Place & Travel', 'Gombe, Tanzania', 'Arrived at Gombe Stream to study chimpanzees; lived in wilderness for years.', 'range', 1960, 1975, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Work & Education', 'Chimp tool-use discovery', 'Observed chimps making tools from grass — first documented non-human tool use.', 'point', 1960, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Work & Education', 'Cambridge PhD in Ethology', 'Earned PhD without an undergraduate degree — a rare academic exception.', 'point', 1965, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Work & Education', 'In the Shadow of Man published', 'Landmark book on chimpanzee behavior; revolutionized primate studies.', 'point', 1971, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Activities', 'Jane Goodall Institute founded', 'Established institute to protect chimpanzees and their habitats worldwide.', 'point', 1977, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Activities', 'Roots & Shoots program', 'Launched global youth environmental action program operating in 60+ countries.', 'range', 1991, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Activities', 'UN Messenger of Peace', 'Appointed UN Messenger of Peace; travels 300 days/year for conservation.', 'range', 2002, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e1', 'Relations & Family', 'Son Hugo ''Grub'' born', 'Son born in Tanzania; raised in the Gombe wilderness with chimpanzees nearby.', 'point', 1967, null, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001e2', 'Place & Travel', 'Isleworth, Middlesex, England', 'Born in suburban London; collected fossils and natural specimens as a child.', 'range', 1926, 1945, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Work & Education', 'Cambridge — Natural Sciences', 'Read Natural Sciences at Clare College, Cambridge; graduated 1947.', 'range', 1945, 1947, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Work & Education', 'BBC Television — producer', 'Joined BBC in 1952; produced early natural history and arts programmes.', 'range', 1952, 1965, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Work & Education', 'BBC2 Controller', 'Served as BBC2 controller; introduced colour television to British broadcasting.', 'range', 1965, 1969, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Work & Education', 'Life on Earth series', '13-part BBC series revolutionized natural history filmmaking; 500M viewers.', 'point', 1979, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Work & Education', 'Planet Earth series', 'Landmark HD documentary; narrated by Attenborough, watched by hundreds of millions.', 'point', 2006, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Activities', 'Climate and nature advocacy', 'Became prominent voice urging action on climate change and biodiversity loss.', 'range', 2000, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Activities', 'A Life on Our Planet', 'Released personal witness statement and vision for the future of nature.', 'point', 2020, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e2', 'Relations & Family', 'Wife Jane died', 'Lost wife Jane of 47 years; continued working prolifically into his 90s.', 'point', 1997, null, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001e3', 'Place & Travel', 'Chicago, Illinois', 'Grew up on South Side of Chicago in a working-class family.', 'range', 1964, 1981, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Work & Education', 'Princeton University', 'Studied sociology and African-American studies; faced racial isolation on campus.', 'range', 1981, 1985, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Work & Education', 'Harvard Law School', 'Earned JD from Harvard Law; worked at Sidley Austin law firm.', 'range', 1985, 1988, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Work & Education', 'Chicago non-profit leadership', 'Led Public Allies and VP of Community Affairs at University of Chicago hospitals.', 'range', 1993, 2009, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Relations & Family', 'Married Barack Obama', 'Married Barack Obama at Trinity United Church of Christ in Chicago.', 'point', 1992, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Place & Travel', 'The White House, Washington D.C.', 'First Black First Lady of the United States; redefined the role with grace.', 'range', 2009, 2017, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Activities', 'Let''s Move! campaign', 'Anti-childhood obesity initiative; reformed school lunch programs nationally.', 'range', 2010, 2017, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Work & Education', 'Becoming memoir published', 'Memoir sold 17M+ copies; became best-selling memoir in US history.', 'point', 2018, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e3', 'Activities', 'When We All Vote initiative', 'Co-chaired non-partisan voter registration organization ahead of 2020 election.', 'range', 2018, 2026, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000001e4', 'Place & Travel', 'Lorain, Ohio', 'Born Chloe Wofford in Lorain; grew up in integrated working-class neighborhood.', 'range', 1931, 1949, '#3b82f6'),
