  ('a0000000-0000-0000-0000-0000000001e4', 'Work & Education', 'The Bluest Eye — debut novel', 'First novel published while raising two sons alone; largely overlooked initially.', 'point', 1970, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e4', 'Work & Education', 'Beloved published', 'Masterwork inspired by true story of enslaved mother; won Pulitzer Prize.', 'point', 1987, null, '#10b981'),
  ('a0000000-0000-0000-0000-0000000001e4', 'Activities', 'Pulitzer Prize for Fiction', 'Won Pulitzer for Beloved (1988); cemented her as America''s foremost novelist.', 'point', 1988, null, '#f59e0b'),
