  ('a0000000-0000-0000-0000-0000000001e4', 'Health', 'Died at 88', 'Died of pneumonia at Montefiore Medical Center, New York.', 'point', 2019, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
